<template>
    <view class="order-detail" :style="themeColor()">
        <view v-if="loading && !order" class="page-state">正在加载订单…</view>
        <view v-if="error" class="page-error"><text>{{ error }}</text><view @click="load">重新加载</view></view>
        <template v-if="order">
            <view class="detail-section status-section"><view class="status-line"><text class="order-status">{{ orderStatusLabel(order) }}</text><text class="channel-tag">{{ paymentLabel(order) }}</text></view><view class="status-amount"><text>订单金额</text><text>¥{{ money(order.order_money) }}</text></view><text v-if="order.close_remark" class="status-hint">{{ order.close_remark }}</text><view class="status-tools"><text @click="copy(order.order_no)">{{ order.order_no }} <text>复制</text></text><view @click="load">刷新状态</view></view></view>
            <view v-if="order.payment_mode === 'offline_credit'" class="detail-section"><OrderCreditSummary :order="order" /></view>
            <view class="detail-section"><view class="section-title">客户与交付</view><view class="customer-line"><view class="customer-main"><text class="customer-name">{{ order.member?.nickname || order.taker_name || '商城客户' }}</text><text class="secondary">{{ customerMobile || '未留手机号' }}</text></view><view v-if="customerMobile" class="text-action" @click="callCustomer">联系客户</view></view><view class="info-row"><text>{{ order.delivery_type_name || '交付方式' }}</text><text>{{ order.delivery_type === 'store' ? order.store?.store_name || '门店信息待核对' : order.taker_name || '—' }}</text></view><view v-if="address" class="address">{{ address }}</view><view v-if="order.buyer_ask_delivery_time" class="info-row"><text>客户预约</text><text>{{ order.buyer_ask_delivery_time }}</text></view></view>
            <view class="detail-section"><view class="section-title">设备清单 <text>{{ goods.length }} 项</text></view><view v-for="item in goods" :key="item.order_goods_id" class="device-row"><image v-if="item.sku_image || item.goods_image" class="device-image" :src="img(item.sku_image || item.goods_image)" mode="aspectFill" @click="previewImage(item)" /><view class="device-main"><text class="device-name">{{ item.goods_name }}</text><text v-if="item.sku_name" class="secondary">{{ item.sku_name }}</text><text v-if="goodsIdentity(item)" class="device-imei" @click="copy(goodsIdentity(item))">IMEI {{ goodsIdentity(item) }} <text>复制</text></text><view class="device-state"><text>{{ item.status_name || '状态待核对' }}</text><text>{{ item.delivery_status_name }}</text><text v-if="item.return_state === 'returned'">设备已收回</text><text v-if="item.can_confirm_received" class="receive-pending">退款后待实物收回</text></view><view class="device-price"><text>¥{{ money(item.price) }} × {{ item.num || 1 }}</text><text v-if="item.return_receiver">收回人 {{ item.return_receiver }}</text></view></view></view></view>
            <view v-if="packages.length" class="detail-section"><view class="section-title">物流记录</view><view v-for="(item, index) in packages" :key="item.id || index" class="package-row"><text>{{ item.express_company_name || item.company?.company_name || item.name || order.delivery_type_name }}</text><text v-if="item.express_number" class="device-imei" @click="copy(item.express_number)">{{ item.express_number }} · 复制</text><text class="secondary">{{ formatOrderTime(item.create_time) }}</text></view></view>
            <view v-if="voucherUrls.length" class="detail-section"><view class="section-title">付款凭证</view><view class="voucher-grid"><image v-for="(url, index) in voucherUrls" :key="url" :src="img(url)" mode="aspectFill" @click="previewVoucher(index)" /></view></view>
            <view v-if="order.return_context_error" class="page-warning">{{ order.return_context_error }}</view>
            <view class="detail-section"><view class="section-title">订单资料 <view class="text-action" @click="showRecords = !showRecords">{{ showRecords ? '收起' : '展开' }}</view></view><view class="info-row"><text>下单时间</text><text>{{ formatOrderTime(order.create_time) }}</text></view><view v-if="order.member_remark" class="remark-row"><text>客户留言</text><text>{{ order.member_remark }}</text></view><view v-if="order.shop_remark" class="remark-row"><text>商家备注</text><text>{{ order.shop_remark }}</text></view><template v-if="showRecords"><view class="info-row"><text>订单来源</text><text>{{ order.order_from_name || '—' }}</text></view><view class="info-row"><text>支付方式</text><text>{{ order.pay?.type_name || paymentLabel(order) }}</text></view><view class="info-row"><text>支付记录金额</text><text>¥{{ money(order.pay_money) }}</text></view><view v-if="order.pay_time && formatOrderTime(order.pay_time) !== '—'" class="info-row"><text>支付时间</text><text>{{ formatOrderTime(order.pay_time) }}</text></view><view v-if="order.finish_time && formatOrderTime(order.finish_time) !== '—'" class="info-row"><text>完成时间</text><text>{{ formatOrderTime(order.finish_time) }}</text></view><view v-for="(item, index) in logs" :key="index" class="log-row"><text>{{ item.type_name || '订单操作' }} · {{ item.main_name || item.main_type_name || '系统' }}</text><text>{{ item.content }}</text><text>{{ formatOrderTime(item.create_time) }}</text></view></template></view>
            <view class="bottom-space" />
            <view class="detail-footer"><view :class="primary ? 'more-button' : 'secondary-action'" @click="showActions">更多操作</view><view v-if="primary" class="primary-button" @click="openAction(primary.key)">{{ primary.label }}</view></view>
        </template>
        <u-action-sheet :show="actionSheet" title="订单操作" :actions="actionItems" cancelText="取消" @close="actionSheet = false" @select="selectAction" />
        <OrderActionPanel :show="panelVisible" :order="order" :action="action" @close="panelVisible = false" @changed="load" />
    </view>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import { img } from '@/utils/common'
import { getOrderDetail } from '@/addon/phone_shop/api/order'
import { formatOrderTime, getOrderActions, goodsIdentity, money, orderGoods, orderStatusLabel, paymentLabel } from '@/addon/phone_shop/utils/orderWorkflow'
import OrderActionPanel from '@/addon/phone_shop/components/OrderActionPanel.vue'
import OrderCreditSummary from '@/addon/phone_shop/components/OrderCreditSummary.vue'
const orderId = ref(0), order = ref<Record<string, any> | null>(null), loading = ref(false), error = ref(''), showRecords = ref(false)
const actionSheet = ref(false), panelVisible = ref(false), action = ref(''), opening = ref(false)
const goods = computed(() => orderGoods(order.value))
const packages = computed(() => Array.isArray(order.value?.order_delivery) ? order.value.order_delivery : [])
const logs = computed(() => Array.isArray(order.value?.order_log) ? order.value.order_log : [])
const customerMobile = computed(() => String(order.value?.taker_mobile || order.value?.member?.mobile || ''))
const address = computed(() => order.value?.delivery_type === 'store' ? order.value?.store?.full_address || '' : order.value?.taker_full_address || '')
const voucherUrls = computed<string[]>(() => Array.isArray(order.value?.offline_record?.voucher_urls) ? order.value!.offline_record.voucher_urls : [])
const actions = computed(() => getOrderActions(order.value))
const primary = computed(() => actions.value.find(item => ['confirm_paid', 'recover_paid', 'delivery', 'finish', 'received'].includes(item.key)))
const actionItems = computed(() => actions.value.map(item => ({ name: item.label, key: item.key, color: item.danger ? '#d14343' : '#263244' })))
onLoad((options: any) => { orderId.value = Number(options?.order_id || options?.id || 0) })
onShow(load)
async function load() {
    if (loading.value) return
    if (!orderId.value) { error.value = '缺少订单编号，请返回订单列表重新打开'; return }
    loading.value = true; error.value = ''
    try { const response: any = await getOrderDetail(orderId.value); if (!response?.data?.order_id) throw new Error('订单资料未返回'); order.value = response.data }
    catch (reason: any) { error.value = reason?.msg || reason?.message || '订单加载失败，请重试' }
    finally { loading.value = false }
}
async function showActions() { if (opening.value || loading.value) return; opening.value = true; await load(); if (!error.value) actionSheet.value = true; opening.value = false }
async function openAction(key: string) { if (opening.value || loading.value) return; opening.value = true; await load(); if (!error.value && actions.value.some(item => item.key === key)) { action.value = key; panelVisible.value = true } else if (!error.value) uni.showToast({ title: '订单状态已变化，请重新查看可用操作', icon: 'none' }); opening.value = false }
function selectAction(item: any) { actionSheet.value = false; action.value = item.key; panelVisible.value = true }
function copy(value: string) { if (value) uni.setClipboardData({ data: String(value) }) }
function callCustomer() { uni.makePhoneCall({ phoneNumber: customerMobile.value }) }
function previewImage(item: any) { const url = img(item.sku_image || item.goods_image); uni.previewImage({ current: url, urls: [url] }) }
function previewVoucher(index: number) { const urls = voucherUrls.value.map(url => img(url)); uni.previewImage({ current: urls[index], urls }) }
</script>
<style scoped lang="scss">
.customer-main { flex: 1; min-width: 0; }
.text-action { flex-shrink: 0; white-space: nowrap; }
.order-detail { min-height: 100vh; padding: 22rpx; box-sizing: border-box; background: #f5f7fa; color: #263244; }.detail-section { padding: 26rpx; margin-bottom: 20rpx; background: #fff; border-radius: 14rpx; }.section-title { display: flex; justify-content: space-between; align-items: center; gap: 16rpx; font-size: 29rpx; font-weight: 600; margin-bottom: 22rpx; }.section-title>text { color: #8590a2; font-size: 24rpx; font-weight: 400; }.status-line { display: flex; align-items: center; gap: 20rpx; flex-wrap: wrap; }.order-status { font-size: 38rpx; font-weight: 650; }.channel-tag { font-size: 24rpx; color: var(--primary-color); }.status-amount { display: flex; justify-content: space-between; align-items: baseline; margin-top: 28rpx; font-size: 26rpx; color: #8590a2; }.status-amount text+text { font-size: 40rpx; font-weight: 600; color: #263244; }.status-hint { display: block; font-size: 24rpx; color: #a16a21; line-height: 1.6; margin-top: 16rpx; }.status-tools { display: flex; justify-content: space-between; gap: 20rpx; margin-top: 24rpx; font-size: 22rpx; color: #8590a2; }.status-tools>text { overflow-wrap: anywhere; flex: 1; }.status-tools view, .status-tools text text, .text-action { color: var(--primary-color); font-size: 24rpx; font-weight: 400; }.customer-line { display: flex; justify-content: space-between; align-items: center; gap: 20rpx; }.customer-name { font-size: 29rpx; margin-right: 20rpx; }.secondary { color: #8590a2; font-size: 24rpx; line-height: 1.5; }.info-row { display: flex; justify-content: space-between; gap: 22rpx; margin-top: 20rpx; font-size: 25rpx; color: #8590a2; }.info-row text+text { color: #516174; text-align: right; overflow-wrap: anywhere; max-width: 75%; }.address { margin-top: 18rpx; font-size: 27rpx; color: #516174; line-height: 1.6; }.device-row { display: flex; gap: 18rpx; padding: 22rpx 0; border-bottom: 1rpx solid #edf0f4; }.device-row:last-child { border-bottom: 0; }.device-image { width: 108rpx; height: 108rpx; flex-shrink: 0; border-radius: 8rpx; background: #f3f5f8; }.device-main { flex: 1; min-width: 0; }.device-main>text { display: block; }.device-name { font-size: 29rpx; line-height: 1.45; }.device-imei { margin-top: 12rpx; font-size: 24rpx; color: #516174; font-family: monospace; overflow-wrap: anywhere; }.device-imei text { color: var(--primary-color); font-family: sans-serif; }.device-state { display: flex; flex-wrap: wrap; gap: 12rpx; margin-top: 14rpx; color: #8590a2; font-size: 23rpx; }.device-state .receive-pending { color: #b9781c; }.device-price { display: flex; justify-content: space-between; gap: 12rpx; margin-top: 14rpx; color: #516174; font-size: 25rpx; }.package-row { display: flex; flex-direction: column; gap: 10rpx; padding: 16rpx 0; border-top: 1rpx solid #edf0f4; font-size: 27rpx; }.voucher-grid { display: flex; flex-wrap: wrap; gap: 18rpx; }.voucher-grid image { width: 138rpx; height: 138rpx; border-radius: 8rpx; background: #f3f5f8; }.remark-row { display: flex; flex-direction: column; gap: 12rpx; margin-top: 22rpx; color: #8590a2; font-size: 25rpx; line-height: 1.6; }.remark-row text+text { color: #516174; white-space: pre-wrap; overflow-wrap: anywhere; }.log-row { display: flex; flex-direction: column; gap: 8rpx; padding: 22rpx 0; margin-top: 14rpx; border-top: 1rpx solid #edf0f4; font-size: 24rpx; color: #8590a2; line-height: 1.6; }.log-row text:first-child { color: #516174; }.bottom-space { height: calc(110rpx + env(safe-area-inset-bottom)); }.detail-footer { position: fixed; bottom: 0; left: 0; right: 0; z-index: 30; display: flex; align-items: center; gap: 22rpx; padding: 20rpx 26rpx calc(20rpx + env(safe-area-inset-bottom)); background: #fff; border-top: 1rpx solid #edf0f4; }.more-button { padding: 18rpx 20rpx; color: #64748b; font-size: 26rpx; flex-shrink: 0; }.primary-button, .secondary-action { flex: 1; padding: 21rpx 22rpx; border-radius: 10rpx; font-size: 28rpx; text-align: center; color: #fff; background: var(--primary-color); }.secondary-action { color: #516174; background: #f2f5f9; }.page-state { padding: 120rpx 0; text-align: center; color: #8590a2; font-size: 27rpx; }.page-error, .page-warning { padding: 20rpx; margin-bottom: 20rpx; background: #fff1f0; color: #b42318; font-size: 25rpx; line-height: 1.6; }.page-error view { color: var(--primary-color); padding-top: 14rpx; }.page-warning { color: #a16a21; background: #fff6e8; }
</style>
